function psAccordionRows(id,k){const rows=psRowsForAds(id,k);if(!rows.length)return`<div class='empty'>ยังไม่มี PS ในทีมนี้</div>`;return`<div class='ps-list'>${rows.map((r,i)=>{const v=metricData(r,k),idx=metricIndex(r,k),s=statusClass(idx),pid=psId(r);return`<button class='ps-row ${s}' data-mode='person' data-ads='${E(id)}' data-ps='${E(pid)}'><div class='ps-row-rank num'>${i+1}</div><div class='ps-row-main'><div class='ps-row-name'>${idx<70?`<span class='warn-icon' aria-label='ต้องเร่ง'>⚠️</span>`:''}<b>${label(r)}</b></div><span>Target <span class='num'>${M(v.target)}</span> · Actual <span class='num'>${M(v.actual)}</span></span>${progressBar(idx,'thin')}</div><strong class='num'>${P(idx)}</strong></button>`}).join('')}</div>`}
function renderAdsAccordion(rows,k,options={}){const openIds=options.openIds||new Set(),forceOpen=!!options.forceOpen,items=eligibleRows(rows,k).sort((a,b)=>metricIndex(b,k)-metricIndex(a,k));if(!items.length)return`<section class='panel'><div class='empty'>ยังไม่มีข้อมูล ADS สำหรับ ${metric(k)}</div></section>`;return`<section class='panel hierarchy-panel'><div class='section-heading'><div><h3>${E(options.title||'ADS Performance')}</h3><span>${metric(k)} · แตะทีมเพื่อดู PS</span></div></div><div class='ads-accordion'>${items.map((r,i)=>{const id=adsId(r),v=metricData(r,k),idx=metricIndex(r,k),s=statusClass(idx),open=forceOpen||openIds.has(id);return`<article class='ads-accordion-item ${s}${open?' open':''}' data-ads-item='${E(id)}'><button class='ads-accordion-head' data-accordion-toggle aria-expanded='${open?'true':'false'}'><span class='ads-rank num'>${i+1}</span><span class='ads-main'><span class='ads-title'>${label(r)}</span><span class='ads-numbers'>Target <span class='num'>${M(v.target)}</span> · Actual <span class='num'>${M(v.actual)}</span></span>${progressBar(idx)}</span><span class='ads-score'><strong class='num'>${P(idx)}</strong><span class='status-badge ${s}'>${statusLabel(idx)}</span></span><span class='chevron' aria-hidden='true'>⌄</span></button><div class='ads-accordion-body'><div class='ads-accordion-inner'>${psAccordionRows(id,k)}</div></div></article>`}).join('')}</div></section>`}
