function avgMetric(list,k){let t=0,a=0,ix=0,c=0;list.forEach(r=>{const v=metricData(r,k);if(k==='cd123'&&N(v.target)<=0)return;t+=N(v.target);a+=N(v.actual);ix+=N(v.index);c++});return{target:c?t/c:0,actual:c?a/c:0,index:c?ix/c:0}}
function avgPack(packs){packs=packs.map(hydratePack);const one=(set,key)=>{const first=packs[0]?.[set]||[];return first.map(b=>{const id=b[key]||b.code,rows=packs.map(p=>(p[set]||[]).find(x=>(x[key]||x.code)===id)).filter(Boolean),r={...b};K().forEach(k=>r[k]=avgMetric(rows,k));return r})};const ds={...(packs[0]?.ds||{})};K().forEach(k=>ds[k]=avgMetric(packs.map(p=>p.ds).filter(Boolean),k));return hydratePack({ds,ads:one('ads','ads'),ps:one('ps','ps')})}
function historyRows(rows,cur){const m=new Map();rows.forEach(x=>{const key=x.reportDate||x.reportKey||x.path;if(!key)return;if(x.path===cur.comparePath||x.path===cur.dataPath||x.reportKey===cur.reportKey)return;if(x.reportDate&&cur.reportDate&&x.reportDate===cur.reportDate)return;if(!m.has(key))m.set(key,x)});let out=[...m.values()];if(cur.reportDate)out=out.filter(x=>!x.reportDate||String(x.reportDate)<String(cur.reportDate));return out.sort((a,b)=>String(b.reportDate||b.reportKey||'').localeCompare(String(a.reportDate||a.reportKey||'')))}
async function oldPack(kind){const hist=await fetchJson('performance/history-index.json',8000),cur=data.meta||{},older=historyRows(Array.isArray(hist)?hist.filter(x=>x.path):[],cur);if(kind==='same'){const pick=older.find(x=>N(x.workdayNo)===N(cur.workdayNo)-12);if(!pick)throw Error('ยังไม่มีข้อมูลตลาดเดิมรอบก่อนในเดือนนี้');return{pick,old:hydratePack(await fetchJson(pick.path,12000))}}if(kind==='avg3'){const picks=older.slice(0,3);if(!picks.length)throw Error('ยังไม่มีข้อมูลย้อนหลังสำหรับค่าเฉลี่ย');return{pick:{reportKey:'เฉลี่ย '+picks.length+' วันล่าสุด'},old:avgPack(await Promise.all(picks.map(x=>fetchJson(x.path,12000))))}}const pick=older[0];if(!pick)throw Error('ยังไม่มีไฟล์วันทำงานก่อนหน้าให้เทียบ');return{pick:{...pick,reportKey:kind==='pace'?'Pace เป้า':pick.reportKey},old:hydratePack(await fetchJson(pick.path,12000))}}
