function cmpNav(){const m=data.meta||{},wd=N(m.workdayNo),market=wd?((wd-1)%12)+1:'-',round=wd?Math.floor((wd-1)/12)+1:'-',items=[['prev','เทียบวันก่อน','ใช้ reportDate ก่อนหน้า'],['same','เทียบตลาดเดิม','ตลาด '+market+' รอบ '+round],['avg3','เฉลี่ย 3 วัน','ย้อนหลัง 3 ไฟล์'],['pace','Pace เป้า','เทียบต้องทำ/วัน']];return`<div class='compare-nav' aria-label='เลือกรูปแบบการเทียบ'>${items.map(([k,t,d])=>`<button class='compare-chip ${state.cmp===k?'on':''}' data-mode='compare' data-cmp='${k}' data-cat='${E(state.cat||'')}' data-ads='${E(state.ads||'')}'><b>${E(t)}</b><span>${E(d)}</span></button>`).join('')}</div>`}
