function diffCard(cur,old,k,i,allowed=true){if(!allowed)return`<div class='delta-row'><span><small class='num'>#${i+1}</small><b>${metric(k)}</b></span><strong class='num'>สูตรย้อนหลังไม่ตรงกัน</strong></div>`;const cv=metricData(cur,k),ov=metricData(old,k),r=comparePair(cv,ov),up=r.d>=0;return`<button class='delta-row cmpCatCard' data-mode='compare' data-cat='${E(k)}' data-cmp='${E(state.cmp)}'><span><small class='num'>#${i+1}</small><b>${metric(k)}</b></span><strong class='num ${up?'up':'dn'}'>${up?'↑ ':'↓ '}${E(deltaDisplay(r.d))}</strong></button>`}
