function compareHero(cur,old,k){const cv=metricData(cur||{},k),ov=metricData(old||{},k),r=comparePair(cv,ov),up=r.d>=0,labelText=state.cmp==='pace'?'เทียบ Pace เป้า':'Delta Index';return`<section class='delta-hero ${up?'up-state':'down-state'}'><span>${metric(k)} · ${E(labelText)}</span><strong class='num ${up?'up':'dn'}'>${up?'↑ ':'↓ '}${E(deltaDisplay(r.d))}</strong><div><span>ล่าสุด <b class='num'>${M(r.a)}</b></span><span>${state.cmp==='pace'?'Pace':'ก่อนหน้า'} <b class='num'>${M(r.b)}</b></span></div></section>`}
function topMovers(cur,old,k){const all=indexDeltas(cur,old,k,'ps'),up=[...all].sort((a,b)=>b.diff-a.diff).slice(0,5),down=[...all].sort((a,b)=>a.diff-b.diff).slice(0,5);return`<section class='top-movers'><div class='movers-group good-group'><h3>ดีขึ้นมากสุด</h3><div>${up.length?up.map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div></div><div class='movers-group bad-group'><h3>ต่ำลงมากสุด — ต้องดูแล</h3><div>${down.length?down.map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div></div></section>`}
async function screenCompare(mySeq){let p;try{p=await safeOldPack(state.cmp)}catch(e){if(mySeq!==seq||state.mode!=='compare')return;app.innerHTML=nav()+`<section class='panel'><div class='empty'>${E(e.message)}</div></section>`;return}if(mySeq!==seq||state.mode!=='compare')return;const cat=state.cat in C?state.cat:'',cd3Ok=cd3Comparable(data,p.old);if(cat==='dc3'&&!cd3Ok){app.innerHTML=nav()+boardHeader('Smart Compare วันต่อวัน','ล่าสุด '+(data.meta?.reportKey||'')+' เทียบกับ '+(p.pick?.reportKey||'ก่อนหน้า'))+cmpNav()+`<section class='panel'><div class='empty'>CD3 ของสองช่วงใช้สูตรไม่เหมือนกันหรือไม่มีข้อมูลยืนยันสูตร จึงไม่แสดงผลเทียบเพื่อป้องกันตัวเลขผิด</div></section>`;return}const primary=(cat||activeMetric())==='dc3'&&!cd3Ok?'sales':(cat||activeMetric());if(!cat){app.innerHTML=nav()+boardHeader('Smart Compare วันต่อวัน','ล่าสุด '+(data.meta?.reportKey||'')+' เทียบกับ '+(p.pick?.reportKey||'ก่อนหน้า'))+cmpNav()+compareHero(data.ds,p.old.ds||{},primary)+`<section class='panel'><div class='section-heading'><div><h3>Metric Delta</h3><span>แตะ metric เพื่อ drill-down ระดับ ADS · จัดอันดับจากการเปลี่ยนแปลง Index</span></div></div><div class='metric-delta-list'>${K().map((k,i)=>diffCard(data.ds,p.old.ds||{},k,i,k!=='dc3'||cd3Ok)).join('')}</div></section>`+topMovers(data.ps,p.old.ps,primary)+status();return}const adsRows=indexDeltas(data.ads,p.old.ads,cat,'ads').sort((a,b)=>b.diff-a.diff),adsList=adsRows.map(x=>x.ads||x.code).filter(Boolean),sel=state.ads&&adsList.includes(state.ads)?state.ads:'';if(sel){const rows=indexDeltas((data.ps||[]).filter(x=>x.ads===sel),(p.old.ps||[]).filter(x=>x.ads===sel),cat,'ps'),up=[...rows].sort((a,b)=>b.diff-a.diff),down=[...rows].sort((a,b)=>a.diff-b.diff);app.innerHTML=nav()+`<section class='panel compare-drill'><button class='back-button' data-mode='compare' data-cat='${E(cat)}' data-cmp='${E(state.cmp)}'>← กลับ</button><div class='section-heading'><div><h3>${E(sel)} · ${metric(cat)}</h3><span>PS ในทีมนี้ · เรียงจากการเปลี่ยนแปลง Index</span></div></div>${cmpNav()}<div class='team-chip-row'>${adsList.map(a=>button(a,{mode:'compare',cat,ads:a,cmp:state.cmp},'chip')).join('')}</div></section><section class='top-movers'><div class='movers-group good-group'><h3>ดีขึ้นมากสุด</h3>${up.length?up.slice(0,5).map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div><div class='movers-group bad-group'><h3>ต่ำลงมากสุด — ต้องดูแล</h3>${down.length?down.slice(0,5).map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div></section>`;return}const allPs=indexDeltas(data.ps,p.old.ps,cat,'ps'),up=[...allPs].sort((a,b)=>b.diff-a.diff).slice(0,5),down=[...allPs].sort((a,b)=>a.diff-b.diff).slice(0,5);app.innerHTML=nav()+`<section class='panel compare-drill'><button class='back-button' data-mode='compare' data-cmp='${E(state.cmp)}'>← กลับ</button><div class='section-heading'><div><h3>รายละเอียด: ${metric(cat)}</h3><span>เลือก ADS เพื่อดู PS · Delta ใช้ Index percentage point</span></div></div>${cmpNav()}</section>${compareHero(data.ds,p.old.ds||{},cat)}<section class='panel'><h3>ADS เปลี่ยนแปลง</h3><div class='mover-list'>${adsRows.length?adsRows.map((r,i)=>drow(r,i,{cat,ads:r.ads||r.code})).join(''):`<div class='empty'>ยังไม่มี ADS ที่มีข้อมูลทั้งสองช่วง</div>`}</div></section><section class='top-movers'><div class='movers-group good-group'><h3>ดีขึ้นมากสุด</h3>${up.length?up.map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div><div class='movers-group bad-group'><h3>ต่ำลงมากสุด — ต้องดูแล</h3>${down.length?down.map((r,i)=>drow(r,i)).join(''):`<div class='empty'>ยังไม่มีข้อมูลที่เทียบกันได้</div>`}</div></section>`}
function screenMs(){return nav()+`<section class='panel fade'><div class='title'>MS แยกโหมด</div><div class='empty'>โหมดนี้ถูกแยกจาก DS/ADS/PS แล้ว และยังไม่มี dataset MS ใน current.min.json จึงไม่แสดงตารางปลอม ถ้ามีไฟล์ MS เพิ่มเข้ามา ระบบควรต่อข้อมูลชุดใหม่โดยไม่ปนกับหน้า Pro หรือ DS.</div></section>`}
function refreshMetricView(){if(!data)return;const k=activeMetric();document.querySelectorAll('[data-metric-key]').forEach(b=>{const on=b.dataset.metricKey===k;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on))});const heroHost=document.querySelector('[data-metric-hero]'),accordionHost=document.querySelector('[data-accordion-host]');if(!heroHost||!accordionHost)return;const openIds=new Set([...accordionHost.querySelectorAll('.ads-accordion-item.open')].map(x=>x.dataset.adsItem).filter(Boolean));if(state.mode==='ds'){const m=data.meta||{},sub='ไฟล์ '+(m.reportKey||'')+' · ภาพรวมทุก ADS';heroHost.innerHTML=hero('DS ภาพรวม',sub,data.ds||summaryRow(data.ps||[],'DS'),k);accordionHost.innerHTML=renderAdsAccordion(data.ads||[],k,{title:'ADS Board',openIds})}else if(state.mode==='ads'){heroHost.innerHTML=hero('ADS ภาพรวม','เลือก metric แล้วแตะทีมเพื่อดู PS',data.ds||summaryRow(data.ps||[],'ADS'),k);accordionHost.innerHTML=renderAdsAccordion(data.ads||[],k,{title:'ADS Performance',openIds})}else if(state.mode==='ps'){const first=adsId((data.ads||[])[0]),sel=state.ads||first,rows=(data.ps||[]).filter(x=>adsId(x)===sel),ads=(data.ads||[]).filter(x=>adsId(x)===sel),summary=summaryRow(rows,sel),fallback=ads.length?ads:[{ads:sel,name:sel,...summary}];heroHost.innerHTML=hero(sel+' · PS','Seller Report Detail',summary,k);accordionHost.innerHTML=renderAdsAccordion(fallback,k,{title:'PS ใน '+sel,forceOpen:true,openIds})}}
function render(){const mySeq=++seq;if(!data){app.innerHTML=`<section class='panel'><div class='empty'>กำลังโหลดข้อมูล...</div></section>`;return}if(state.mode==='ads')app.innerHTML=screenAds();else if(state.mode==='ps')app.innerHTML=screenPs();else if(state.mode==='person')app.innerHTML=screenPerson();else if(state.mode==='compare')screenCompare(mySeq);else if(state.mode==='ms')app.innerHTML=screenMs();else app.innerHTML=screenDs()}
load().catch(e=>{app.innerHTML=nav()+`<section class='panel'><div class='title'>ยังไม่พบข้อมูลแบบเร็ว</div><div class='empty'>${E(e.message)}<br><br>ให้ไป Admin → เลือกไฟล์ Tracking → อัปโหลด Performance JSON + ตั้งล่าสุด</div></section>`})
